// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');

const { fontFamily: montserratFamily } = loadMontserrat();



export type TheInsightfulPresenceProps = Record<string, any>;

const TheInsightfulPresence: React.FC<TheInsightfulPresenceProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 10,
  title = "SUPPORT CAN LOOK SIMPLE",
  items = [
    "A CHECKLIST",
    "A REMINDER",
    "A SLOWER FIRST PASS",
    "A CLEARER NEXT STEP",
    "A BREATH BEFORE YOU RESPOND",
  ],
  deepBlue = "#071B33",
  lightBlue = "#4A90E2",
  blackColor = "#000000",
  whiteColor = "#F5F7FA",
  particleCount = 40,
  glowOpacity = 0.4,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background rendering logic
  const bgStyle = transparentBackground
    ? "transparent"
    : `radial-gradient(circle at 50% 120%, ${deepBlue} 0%, ${blackColor} 80%)`;

  const fallbackBgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive metrics
  const titleFontSize = height * 0.055;
  const itemFontSize = height * 0.035;
  const dotSize = height * 0.012;
  const safeMarginLeftRight = width * 0.15;
  const safeMarginTop = height * 0.15;

  // Cinematic Title Animation (Fade in + Slow drift upwards)
  const titleOpacity = interpolate(frame, [10, 45], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const titleY = interpolate(frame, [10, 90], [height * 0.02, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const titleTracking = interpolate(frame, [10, 150], [0.1, 0.15], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Center glow pulse
  const glowPulse = interpolate(
    Math.sin(frame * 0.05),
    [-1, 1],
    [glowOpacity * 0.8, glowOpacity * 1.2]
  );

  // Deterministic Particles
  const particles = useMemo(() => {
    return Array.from({ length: particleCount }).map((_, i) => ({
      x: random(`x-${i}`) * width,
      y: random(`y-${i}`) * height,
      size: random(`size-${i}`) * 3 + 1.5,
      speed: random(`speed-${i}`) * 0.5 + 0.1,
      opacityBase: random(`op-${i}`) * 0.4 + 0.1,
    }));
  }, [particleCount, width, height]);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: fallbackBgColor,
        background: bgStyle,
        fontFamily: montserratFamily,
        color: whiteColor,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        overflow: "hidden",
      }}
    >
      {/* Background Glow */}
      <div
        style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          transform: "translate(-50%, -50%)",
          width: width * 0.7,
          height: height * 0.7,
          background: `radial-gradient(circle, ${lightBlue} 0%, transparent 60%)`,
          opacity: transparentBackground ? 0 : glowPulse,
          filter: "blur(120px)",
          pointerEvents: "none",
          transition: "none",
        }}
      />

      {/* Floating Particles */}
      {!transparentBackground && particles.map((p, i) => {
        const yOffset = frame * p.speed * (height * 0.005);
        const yPos = (p.y - yOffset) % height;
        // Handle wrap-around math for seamless negative Y
        const finalY = yPos < -100 ? height + (yPos % height) : yPos;

        const pOpacity = interpolate(
          Math.sin(frame * 0.03 + i),
          [-1, 1],
          [p.opacityBase * 0.2, p.opacityBase]
        );

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: p.x,
              top: finalY,
              width: p.size,
              height: p.size,
              backgroundColor: lightBlue,
              borderRadius: "50%",
              opacity: pOpacity,
              boxShadow: `0 0 ${p.size * 2}px ${lightBlue}`,
              transition: "none",
            }}
          />
        );
      })}

      {/* Content Container with Safe Margins */}
      <div
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          paddingTop: safeMarginTop,
          paddingLeft: safeMarginLeftRight,
          paddingRight: safeMarginLeftRight,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          boxSizing: "border-box",
          transition: "none",
        }}
      >
        {/* Title Area */}
        <h1
          style={{
            fontSize: titleFontSize,
            fontWeight: 800,
            textAlign: "center",
            textTransform: "uppercase",
            letterSpacing: `${titleTracking}em`,
            margin: 0,
            opacity: titleOpacity,
            transform: `translateY(${titleY}px)`,
            textShadow: `0 4px 12px rgba(0,0,0,0.5)`,
            transition: "none",
          }}
        >
          {title}
        </h1>

        {/* List Items Container */}
        <div
          style={{
            marginTop: height * 0.12,
            display: "flex",
            flexDirection: "column",
            alignItems: "flex-start",
            gap: height * 0.04,
            transition: "none",
          }}
        >
          {items.map((item, index) => {
            const staggerDelay = 40 + index * 12;
            
            const itemOpacity = interpolate(
              frame,
              [staggerDelay, staggerDelay + 25],
              [0, 1],
              { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
            );

            const itemY = interpolate(
              frame,
              [staggerDelay, staggerDelay + 35],
              [20, 0],
              { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
            );

            const dotScale = spring({
              fps,
              frame: frame - staggerDelay,
              config: { damping: 12, stiffness: 90 },
              durationInFrames: 30,
            });

            return (
              <div
                key={index}
                style={{
                  display: "flex",
                  alignItems: "center",
                  flexDirection: "row",
                  opacity: itemOpacity,
                  transform: `translateY(${itemY}px)`,
                  transition: "none",
                }}
              >
                {/* Checkmark / Dot */}
                <div
                  style={{
                    width: dotSize,
                    height: dotSize,
                    borderRadius: "50%",
                    backgroundColor: lightBlue,
                    marginRight: width * 0.015,
                    transform: `scale(${Math.max(0, dotScale)})`,
                    boxShadow: `0 0 12px ${lightBlue}`,
                    flexShrink: 0,
                    transition: "none",
                  }}
                />
                
                {/* List Text */}
                <span
                  style={{
                    fontSize: itemFontSize,
                    fontWeight: 700,
                    letterSpacing: "0.05em",
                    textTransform: "uppercase",
                    textShadow: `0 2px 8px rgba(0,0,0,0.6)`,
                    transition: "none",
                  }}
                >
                  {item}
                </span>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default TheInsightfulPresence;